import pandas as pd
import numpy as np

DEFAULT_COLUMNS = ['Element', 'Count']

def task_func(elements, include_index=False):
    elements_list = [] if elements is None else list(elements)
    counts = [len(str(element)) for element in elements_list]

    if include_index:
        return pd.DataFrame(
            {
                'Index': list(range(len(elements_list))),
                'Element': elements_list,
                'Count': counts,
            },
            columns=['Index', 'Element', 'Count'],
        )

    return pd.DataFrame(
        {
            'Element': elements_list,
            'Count': counts,
        },
        columns=DEFAULT_COLUMNS,
    )
